mapper.select:
SELECT

FROM operation_log l


        AND l.module = #{q.module}


        AND l.status = #{q.status}


        AND (l.username LIKE CONCAT('%', #{q.keyword}, '%')
             OR l.operation LIKE CONCAT('%', #{q.keyword}, '%')
             OR l.request_uri LIKE CONCAT('%', #{q.keyword}, '%'))


        AND l.create_time >= #{q.startDate}



        AND l.create_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)


ORDER BY l.id DESC
